CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), content TEXT NOT NULL, source_url TEXT, source_type TEXT NOT NULL CHECK(source_type IN ('news', 'paper', 'tech', 'custom')), category TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')), priority INTEGER NOT NULL DEFAULT 5, viewed_at TEXT DEFAULT NULL);
CREATE TABLE IF NOT EXISTS interactions (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), post_id TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('like', 'dislike', 'save')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')));
